<?php
require __DIR__.'/../includes/upb_bj_report.php';
function reportCheck($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
function reportRead(string $bytes,?callable $edit=null){$p=tempnam('/tmp','upb-report-test-');try{file_put_contents($p,$bytes);$z=new ZipArchive();$z->open($p);$d=upbBjXml($z->getFromName('content.xml'));if(!$edit){$z->close();return $d;}$edit($d);$z->addFromString('content.xml',$d->saveXML());$z->close();return file_get_contents($p);}finally{unlink($p);}}
$current=reportRead(buildUpbBjInputTemplateOds('2026-02'),function($d){foreach(['JANUARI'=>100000,'FEBRUARI'=>260000] as $name=>$value){$t=upbBjTables($d)[$name];$r=1;foreach($t->childNodes as $row){if(!$row instanceof DOMElement||$row->localName!=='table-row')continue;if($r===7){$cell=upbBjColumnCell($row,9);$cell->setAttributeNS(UPB_O,'office:value-type','float');$cell->setAttributeNS(UPB_O,'office:value',(string)$value);$cell->appendChild($d->createElementNS(UPB_X,'text:p',(string)$value));break;}$r+=max(1,(int)$row->getAttributeNS(UPB_T,'number-rows-repeated'));}upbBjApplySubtotals($t);}});
$prior=reportRead(buildUpbBjInputTemplateOds('2025-12'),function($d){$m=0;foreach(upbBjTables($d) as $name=>$t){if($name==='KESIMPULAN')continue;$m++;$b=upbBjBottom($t);$cells=upbBjCells($t);$row=(int)substr($b['FARMASI']['ref'],1);$cells[$row][9]->setAttributeNS(UPB_O,'office:value',(string)($m*1000));}});
$out=buildUpbBjReportOds('2026-02',$current,$prior);$d=reportRead($out);$tables=upbBjTables($d);reportCheck(array_keys($tables)===['UPB BJ kx'],'One UPB report sheet');$t=$tables['UPB BJ kx'];$cells=upbBjCells($t);
foreach([11=>[1,1,2,12],18=>[100,160,260,260]] as $r=>$v){foreach([12,13,10,24] as $i=>$c)reportCheck((float)$cells[$r][$c]->getAttributeNS(UPB_O,'value')===$v[$i]*1.0,'Current/prior monthly and YTD/full year values');}
$positions=[];$rowNodes=[];$r=1;foreach($t->childNodes as $row)if($row instanceof DOMElement&&$row->localName==='table-row'){$rowNodes[$r]=$row;if(isset($cells[$r][5])&&preg_match('/Mulai 01\/2026 Hingga (01|02)\/2026/',$cells[$r][5]->textContent,$m))$positions[$m[1]]=$r;$r+=max(1,(int)$row->getAttributeNS(UPB_T,'number-rows-repeated'));}
reportCheck($positions['01']<$positions['02'],'January before February');reportCheck($rowNodes[$positions['01']]->getAttributeNS(UPB_T,'visibility')==='collapse','Previous month hidden');reportCheck($rowNodes[$positions['02']]->getAttributeNS(UPB_T,'visibility')!=='collapse','Selected month visible');$offset=$positions['02']-1;$formula=$cells[$offset+8][9]->getAttributeNS(UPB_T,'formula');reportCheck($formula==='of:=SUM([.I'.($offset+7).':.I'.($offset+7).'])','Monthly subtotal references shifted with block');
$z=new ZipArchive();$z->open(__DIR__.'/../dashboard/assets/input-templates/upb-bj-kx-report.ods');$original=array_values(upbBjTables(upbBjXml($z->getFromName('content.xml'))))[0];$z->close();$before=upbBjCells($original);foreach($before as $r=>$cols)if($r<=21)foreach([4,5,6] as $c)if(isset($cols[$c])){reportCheck(($cells[$r][$c]->textContent??'')===$cols[$c]->textContent,'Pareto text untouched');reportCheck(($cells[$r][$c]??null)?->getAttributeNS(UPB_T,'formula')===$cols[$c]->getAttributeNS(UPB_T,'formula'),'Pareto formula untouched');}
reportCheck(upbBjReportFormula("of:=['JANUARI'.I8]-['FEBRUARI'.I8]",200,['JANUARI'=>24,'FEBRUARI'=>212])==='of:=[.I32]-[.I220]','Cross-month references stay in combined sheet');
$style=null;foreach($d->getElementsByTagNameNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','style') as $node)if($node->getAttributeNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','name')==='UPBReportNumber')$style=$node;
reportCheck($style!==null,'Report numeric style exists');$properties=$style->getElementsByTagNameNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','table-cell-properties')->item(0);reportCheck($properties&&$properties->getAttributeNS('urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0','border')==='0.5pt solid #000000','Numeric style directly defines full table borders');
foreach([11,12,13,14,18,19,20,21] as $r)foreach(array_merge([10],range(12,24)) as $c)reportCheck(upbBjColumnCell($rowNodes[$r],$c)->getAttributeNS(UPB_T,'style-name')==='UPBReportNumber','Filled and empty summary cells retain borders');
foreach([[9,9],[9,12],[16,9],[16,12]] as [$r,$c])reportCheck($cells[$r][$c]->getElementsByTagNameNS(UPB_X,'p')->length===1,'Titles use visible ODF paragraphs');
file_put_contents('/tmp/upb-database-report-test.ods',$out);echo "PASS: database-sourced current/prior summaries, chronological monthly blocks, previous rows hidden, latest visible, shifted formulas and untouched Pareto.\n";
